using System;
using UnityEngine;
using Pvp.Map;
using Pvp.Network;
using Pvp.Rules;
using Pvp.Traffic;
using Pvp.Competition;
namespace Pvp.Tests.EditMode {
public static class PvpRuleTrafficTests {
 static int checks;static PvpMapRuntime map;
 static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("PVP_RULES: "+label);}
 static PvpRuleAuthority New(out PvpScoreLedger ledger){var value=new PvpScoreLedger();ledger=value;return new PvpRuleAuthority(map,"rules-test",(p,id,rev,amount,t)=>value.ApplyIncident(p,id,rev,amount,t));}
 static void Feed(PvpRuleAuthority rule,int tick,int edge,Vector3 a,Vector3 b,float speed,int nextEdge=-1,float brake=0,int contact=0,bool eligible=true,PvpTrafficSnapshot? snapshot=null){
  var before=new PvpDriveSnapshot{Edge=edge,Fraction=.5f,Connected=true,State=new Pvp.Driving.PvpVehicleState{Position=a,Speed=speed,YawDegrees=edge==8?180:90}};var after=before;after.State.Position=b;if(contact>0)after.State.Speed=0;if(nextEdge>=0)after.Edge=nextEdge;
  rule.Observe(0,before,after,new PvpMotionTrace{Tick=tick,Applied=eligible,Brake=brake,Attempted=contact>0?a+new Vector3(.2f,0,0):b,ContactKind=contact,ContactId=0},snapshot??PvpTrafficAuthority.At(tick),eligible);
 }
 static Vector3 South(float x){return new Vector3(x,0,-60);}
 public static void Run(){checks=0;var d=PvpMapDefinition.CreateDefault();try{map=new PvpMapRuntime(d);PvpScoreLedger ledger;
  var rule=New(out ledger);Feed(rule,300,0,South(-10.1f),South(-9.9f),10);Check(ledger.Read(0).Penalty==2,"red stop-line");Feed(rule,300,0,South(-10.1f),South(-9.9f),10);Check(ledger.Read(0).Penalty==2,"same tick replay ignored");ledger.Complete(0,"between",10000,300);Feed(rule,301,0,South(-4.1f),South(-3.9f),10);Check(ledger.Read(0).Penalty==7&&ledger.Sequence==4,"same approach upgrade only delta");ledger.Complete(0,"after",10000,302);Check(ledger.Read(0).Bonus==10,"late signal upgrade stays in original safety segment");
  var legal=New(out ledger);Feed(legal,100,0,South(-4.1f),South(-3.9f),10);Feed(legal,250,0,South(-.1f),South(.1f),10,1);Check(ledger.Read(0).Penalty==0,"green entry may clear after red change");
  var transition=New(out ledger);Feed(transition,249,0,South(-10.4f),South(-10.2f),10);Feed(transition,250,0,South(-10.2f),South(-9.99f),10,-1,1);Check(ledger.Read(0).Penalty==0&&transition.Recent().Length>0,"unavoidable transition braking deferred");
  var fast=New(out ledger);for(int i=0;i<25;i++)Feed(fast,100+i,1,South(20+i*.28f),South(20+(i+1)*.28f),14);Check(ledger.Read(0).Penalty==3,"speed requires sustained observation");Feed(fast,125,1,South(28),South(28.4f),20);Check(ledger.Read(0).Penalty==7,"speed severity upgrades same episode");Feed(fast,126,1,South(28.4f),South(28.4f),0,-1,0,0,false);for(int t=127;t<157;t++)Feed(fast,t,1,South(29),South(29.4f),20);Check(ledger.Read(0).Penalty==7,"isolation/reconnect cannot duplicate active speeding");for(int t=157;t<182;t++)Feed(fast,t,1,South(29),South(29.2f),10);for(int t=182;t<207;t++)Feed(fast,t,1,South(29),South(29.28f),14);Check(ledger.Read(0).Penalty==10,"new speeding after clear is new episode");
  var wrong=New(out ledger);for(int t=100;t<125;t++)Feed(wrong,t,1,South(40),South(39.96f),-2);Check(ledger.Read(0).Penalty==5,"sustained wrong direction");var parking=New(out ledger);for(int t=100;t<150;t++)Feed(parking,t,8,new Vector3(0,0,-70),new Vector3(0,0,-69.96f),-2);Check(ledger.Read(0).Penalty==0,"permitted bay reverse protected");
  var actor=new PvpTrafficActor{Id=0,Kind=1,Edge=1,Xmm=30000,Zmm=-60000,Yaw=90,SpeedMm=0,Active=true};var state=PvpTrafficAuthority.At(100);state.Npcs=new[]{actor};
  var rear=New(out ledger);for(int t=100;t<112;t++){state.Tick=t;Feed(rear,t,1,South(20),South(20.28f),14,-1,0,0,true,state);}state.Tick=112;Feed(rear,112,1,South(26.5f),South(26.5f),14,-1,0,1,true,state);Check(ledger.Read(0).Penalty==5,"observed closing rear contact confirmed");
  var victim=New(out ledger);Feed(victim,112,1,South(26.5f),South(26.5f),0,-1,0,1,true,state);Check(ledger.Read(0).Penalty==0&&victim.Recent()[0].Deferred,"stationary contact cannot assign blame");
  var ped=New(out ledger);var walk=PvpTrafficAuthority.At(300);walk.Pedestrians=new[]{new PvpTrafficActor{Kind=2,Id=0,Active=true,Xmm=-6000,Zmm=-60000}};for(int t=300;t<311;t++){walk.Tick=t;Feed(ped,t,0,South(-14),South(-13.8f),10,-1,0,0,true,walk);}walk.Tick=311;Feed(ped,311,0,South(-8.5f),South(-8.5f),10,-1,0,2,true,walk);Check(ledger.Read(0).Penalty==9,"actual protected crossing and observed powered approach");
  var brake=New(out ledger);Feed(brake,311,0,South(-8.5f),South(-8.5f),2,-1,1,2,true,walk);Check(ledger.Read(0).Penalty==0,"necessary avoidance braking protected");
  var noStop=New(out ledger);Feed(noStop,100,0,South(-4.1f),South(-3.9f),10);Feed(noStop,101,0,South(-.1f),new Vector3(0,0,-60.1f),3,8);Check(ledger.Read(0).Penalty==3,"actual right turn without required stop");
  var stopped=New(out ledger);for(int t=100;t<115;t++)Feed(stopped,t,0,South(-12),South(-12),0);int tick=115;for(float x=-12;x<-.15f;x+=.2f)Feed(stopped,tick++,0,South(x),South(x+.2f),10);Feed(stopped,tick,0,South(-.1f),new Vector3(0,0,-60.1f),3,8);Check(ledger.Read(0).Penalty==0,"completed mandatory stop survives acceleration into turn");
  var interrupted=New(out ledger);for(int t=100;t<109;t++)Feed(interrupted,t,0,South(-12),South(-12),0);Feed(interrupted,109,0,South(-12),South(-12),0,-1,0,0,false);Feed(interrupted,110,0,South(-12),South(-12),0);tick=111;for(float x=-12;x<-.15f;x+=.2f)Feed(interrupted,tick++,0,South(x),South(x+.2f),10);Feed(interrupted,tick,0,South(-.1f),new Vector3(0,0,-60.1f),3,8);Check(ledger.Read(0).Penalty==3,"interrupted partial stop cannot become a completed stop");
  var staleRear=New(out ledger);for(int t=100;t<109;t++)Feed(staleRear,t,1,South(20),South(20.28f),14,-1,0,0,true,state);Feed(staleRear,109,1,new Vector3(20,0,-50),new Vector3(20.2f,0,-50),14,-1,0,0,true,state);Feed(staleRear,110,1,South(20),South(20.28f),14,-1,0,0,true,state);Feed(staleRear,111,1,South(26.5f),South(26.5f),14,-1,0,1,true,state);Check(ledger.Read(0).Penalty==0,"disjoint rear observations cannot assign contact blame");
  var stalePed=New(out ledger);for(int t=300;t<309;t++)Feed(stalePed,t,0,South(-14),South(-13.8f),10,-1,0,0,true,walk);Feed(stalePed,309,0,South(-14),South(-14),0,-1,0,0,false,walk);Feed(stalePed,310,0,South(-14),South(-13.8f),10,-1,0,0,true,walk);Feed(stalePed,311,0,South(-8.5f),South(-8.5f),10,-1,0,2,true,walk);Check(ledger.Read(0).Penalty==0,"isolated pedestrian observations expire");
  var unsupported=PvpMapDefinition.CreateDefault();try{unsupported.Nodes[4]+=Vector3.right;bool rejected=false;try{new PvpNpcAuthority(new PvpMapRuntime(unsupported));}catch(ArgumentException){rejected=true;}Check(rejected,"fixed traffic layout rejects changed geometry");}finally{UnityEngine.Object.DestroyImmediate(unsupported);}
  var npcs=new PvpNpcAuthority(map);var previous=npcs.Snapshot();bool redWait=false,playerWait=false;for(int t=1;t<=5000;t++){npcs.Advance(t,null);var s=npcs.Snapshot();Check(s.Npcs.Length==2&&s.Pedestrians.Length==1,"shared actor identities");for(int i=0;i<2;i++){Check(Vector3.Distance(previous.Npcs[i].Position,s.Npcs[i].Position)<.123f,"NPC continuous movement without warp");Check(s.Npcs[i].SpeedMm<=6000,"NPC bounded speed");redWait|=s.Npcs[i].StopReason==1;}previous=s;}Check(redWait,"NPC reacts to signal");
  var blockedNpcs=new PvpNpcAuthority(map);for(int t=1;t<=1000;t++){var player=new PvpDriveSnapshot{Connected=true,State=new Pvp.Driving.PvpVehicleState{Position=new Vector3(60,0,-20)}};blockedNpcs.Advance(t,new[]{player});foreach(var npc in blockedNpcs.Snapshot().Npcs)playerWait|=npc.StopReason==3;}Check(playerWait,"NPC yields to player without pushing/despawn");
  var pedestrianSafety=new PvpNpcAuthority(map);for(int t=1;t<=600;t++){var occupied=new PvpDriveSnapshot{Connected=true,State=new Pvp.Driving.PvpVehicleState{Position=new Vector3(-6,0,-60)}};pedestrianSafety.Advance(t,new[]{occupied});foreach(var actorSafety in pedestrianSafety.Snapshot().Pedestrians)Check(Vector3.Distance(actorSafety.Position,occupied.State.Position)>=2,"pedestrian waits for occupied crossing instead of walking through stopped car");}
  var midCrossing=new PvpNpcAuthority(map);midCrossing.Advance(275,null);var crossingActor=midCrossing.Snapshot().Pedestrians[0];var approachingCar=new PvpDriveSnapshot{Connected=true,State=new Pvp.Driving.PvpVehicleState{Position=crossingActor.Position+Vector3.forward*2.61f}};midCrossing.Advance(276,new[]{approachingCar});Check(Vector3.Distance(midCrossing.Snapshot().Pedestrians[0].Position,approachingCar.State.Position)>=2.6f,"moving pedestrian must not enter vehicle contact band");
  var escapeState=PvpTrafficAuthority.At(276);escapeState.Pedestrians=new[]{new PvpTrafficActor{Kind=2,Id=0,Active=true,Xmm=-6000,Zmm=-64000}};int hitKind,hitId;Check(!PvpNpcAuthority.Contact(escapeState,map,new Vector3(-6,0,-61.5f),new Vector3(-6,0,-61.4f),276,out hitKind,out hitId),"overlapping actor allows separating movement");
  var escapeMotor=new PvpNetworkMotor(map,0,true);var escapePose=escapeMotor.Capture();escapePose.Edge=0;escapePose.Fraction=.9f;escapePose.State.Position=new Vector3(-6,0,-61.5f);escapePose.State.YawDegrees=0;escapeMotor.Restore(escapePose);escapeMotor.ObserveTraffic(escapeState);escapeMotor.Step(new Pvp.Driving.PvpVehicleInput(1,0,0),276);Check(escapeMotor.Capture().State.Position.z>escapePose.State.Position.z&&escapeMotor.TravelDistance>0,"actual motor can separate from overlapping pedestrian");
  var roundtrip=JsonUtility.FromJson<PvpSharedWorld>(JsonUtility.ToJson(new PvpSharedWorld{Traffic=previous}));Check(roundtrip.Traffic.Signature==previous.Signature,"exact shared actors survive wire snapshot");
  Debug.Log("PVP_RULE_TRAFFIC_MODEL_OK checks="+checks+" signal/right/speed/direction/contact/defer/replay/NPC");
 }finally{UnityEngine.Object.DestroyImmediate(d);}}
}}
